package com.bank.sheet.service;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Merges K sorted arrays into one sorted array using a size-K min-heap.
public class SettlementSheetService {
    private static final Logger log = Logger.getLogger(SettlementSheetService.class.getName());

    public int[] mergeKArrays(int[][] arrays) {
        int total = 0;
        for (int[] a : arrays) total += a.length;          // known output size
        int[] result = new int[total];
        // Heap entry: {value, arrayIndex, elementIndex}; ordered by value.
        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i].length > 0) pq.add(new int[]{arrays[i][0], i, 0});
        }
        int idx = 0;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            result[idx++] = top[0];                        // append global minimum
            int ai = top[1], ei = top[2];
            if (ei + 1 < arrays[ai].length) {
                pq.add(new int[]{arrays[ai][ei + 1], ai, ei + 1});  // successor
            }
        }
        log.info(() -> "Merged " + arrays.length + " arrays, " + result.length + " elements");
        return result;
    }
}
