package com.bank.sheet;

import com.bank.sheet.service.SettlementSheetService;
import java.util.Arrays;
import java.util.logging.Logger;

public class SettlementSheetApplication {
    private static final Logger log = Logger.getLogger(SettlementSheetApplication.class.getName());

    public static void main(String[] args) {
        SettlementSheetService service = new SettlementSheetService();
        int[][] arrays = {
            {5, 12, 19},       // desk 1 sorted settlements
            {3, 8, 20},        // desk 2 sorted settlements
            {1, 14}            // desk 3 sorted settlements
        };
        int[] merged = service.mergeKArrays(arrays);
        log.info("Merged settlement sheet: " + Arrays.toString(merged));
    }
}
